import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** TreeSet ordered by length alone; returned as a list. */
    static List<String> byLengthOnly(Collection<String> xs) {
        var set = new TreeSet<String>(Comparator.comparingInt(String::length));
        set.addAll(xs);
        return List.copyOf(set);
    }

    /** TreeSet ordered by length, then alphabetically; returned as a list. */
    static List<String> byLengthThenAlpha(Collection<String> xs) {
        var set = new TreeSet<String>(Comparator.comparingInt(String::length).thenComparing(Comparator.naturalOrder()));
        set.addAll(xs);
        return List.copyOf(set);
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("length-only drops a same-length word", () ->
            eq(byLengthOnly(List.of("bee", "cat", "ox")), List.of("ox", "bee")));
        test("length-only keeps two of three distinct words", () ->
            eq(byLengthOnly(List.of("bee", "cat", "ox")).size(), 2));
        test("a tie-breaker keeps every word", () ->
            eq(byLengthThenAlpha(List.of("bee", "cat", "ox")), List.of("ox", "bee", "cat")));
        test("all the same length leaves one survivor (boundary)", () ->
            eq(byLengthOnly(List.of("aa", "bb", "cc")), List.of("aa")));
