// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** A tag whose name compares case-insensitively. */
    static final class Tag {
        final String name;
        final String key;

        Tag(String name) {
            this.name = name;
            this.key = normalise(name);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            return key.equals(((Tag) o).key);
        }

        @Override
        public int hashCode() {
            return key.hashCode();
