// ─────────────────────────────────────────────────────────────────────────
//  06 · null-safe by helper                                          ★☆☆
//  concepts: Objects.equals · Objects.hash · Objects.requireNonNullElse
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** A customer; region may be null. */
    static final class Customer {
        final String id;
        final String region;

        Customer(String id, String region) {
            this.id = id;
            this.region = region;
        }
    }

    /** Both null → true, one null → false, else both fields equal (null-safe). */
    static boolean sameCustomer(Customer a, Customer b) {
        if (a == null || b == null) return a == b;
        return Objects.equals(a.id, b.id) && Objects.equals(a.region, b.region);
    }

    /** A hash of id and region that tolerates a null region. */
    static int codeOf(Customer c) {
        return Objects.hash(c.id, c.region);
    }

    /** The nickname, or "guest" when it is null. */
    static String labelOr(String nick) {
        return Objects.requireNonNullElse(nick, "guest");
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("two null customers are the same (boundary)", () ->
            ok(sameCustomer(null, null)));
