    }

    /** A copy with areas in DESCENDING order; same-area tickets still keep their input order. */
    static List<Ticket> byAreaDescendingKeepingArrival(List<Ticket> ts) {
        var copy = new ArrayList<>(ts);
        copy.sort(Comparator.comparing(Ticket::area, Comparator.reverseOrder()));
        return copy;
    }

    /** The arrivals of one area, in that stable order. */
    static List<Integer> arrivalsFor(List<Ticket> ts, String area) {
        return byAreaKeepingArrival(ts).stream().filter(t -> t.area().equals(area)).map(Ticket::arrival).toList();
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("sorting by area keeps arrival order inside each area", () ->
            eq(byAreaKeepingArrival(List.of(new Ticket("b", 1), new Ticket("a", 2), new Ticket("b", 3), new Ticket("a", 4))),
                List.of(new Ticket("a", 2), new Ticket("a", 4), new Ticket("b", 1), new Ticket("b", 3))));
        test("arrivalsFor reads one area in stable order", () ->
            eq(arrivalsFor(List.of(new Ticket("b", 1), new Ticket("a", 2), new Ticket("b", 3), new Ticket("a", 4)), "a"), List.of(2, 4)));
        test("arrivalsFor reads the other area too", () ->
            eq(arrivalsFor(List.of(new Ticket("b", 1), new Ticket("a", 2), new Ticket("b", 3), new Ticket("a", 4)), "b"), List.of(1, 3)));
        test("descending areas still keep arrival order inside each area", () ->
            eq(byAreaDescendingKeepingArrival(List.of(new Ticket("b", 1), new Ticket("a", 2), new Ticket("b", 3), new Ticket("a", 4))),
                List.of(new Ticket("b", 1), new Ticket("b", 3), new Ticket("a", 2), new Ticket("a", 4))));
        test("a single area leaves the input order untouched (boundary)", () ->
            eq(byAreaKeepingArrival(List.of(new Ticket("a", 3), new Ticket("a", 1), new Ticket("a", 2))),
                List.of(new Ticket("a", 3), new Ticket("a", 1), new Ticket("a", 2))));
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

