// ─────────────────────────────────────────────────────────────────────────
//  09 · the key that vanished                                        ★★☆
//  concepts: HashMap buckets · mutable keys · stranded entries
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** A stock-keeping unit, equal and hashed by its code, which (unwisely) can change. */
    static final class Sku {
        String code;

        Sku(String code) {
            this.code = code;
        }

        @Override
        public boolean equals(Object o) {
            return o instanceof Sku other && code.equals(other.code);
        }

        @Override
        public int hashCode() {
            return code.hashCode();
        }

        @Override
        public String toString() {
            return code;
        }
    }

    /** Move sku's quantity to newCode: afterwards the map finds it under newCode and not under the old code. */
    static void rename(Map<Sku, Integer> stock, Sku sku, String newCode) {
        Integer quantity = stock.remove(sku);
        sku.code = newCode;
        if (quantity != null) stock.put(sku, quantity);
    }

    /** How many entries the map still holds but can no longer find by their own key. */
    static int strandedEntries(Map<Sku, Integer> stock) {
        int stranded = 0;
        for (Sku key : stock.keySet()) {
            if (!stock.containsKey(key)) stranded++;
        }
        return stranded;
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("a renamed sku is found under its new code", () -> {
            var a1 = new Sku("A1");
